	Val  int
	Next *Node
}

func reverse(head *Node) *Node {
	var prev *Node
	curr := head

	for curr != nil {
		next := curr.Next      // Guardar el siguiente
		curr.Next = prev       // Invertir el puntero
		prev = curr            // Avanzar prev
		curr = next            // Avanzar curr
	}

	return prev
}
```

**Cómo funciona:**
- Tres punteros: `prev` (nodo anterior), `curr` (actual), `next` (siguiente temporal)
- En cada iteración invertimos el puntero `curr.Next` para que apunte hacia atrás
- Avanzamos los punteros hasta el final

**Complejidad:** O(n) tiempo, O(1) espacio

## 2. **Recursivo** — Más elegante pero usa stack

```go
func reverseRecursive(head *Node) *Node {
	if head == nil || head.Next == nil {
		return head
	}

	newHead := reverseRecursive(head.Next)
	head.Next.Next = head      // Invertir el puntero
	head.Next = nil            // Evitar ciclo
	return newHead
}
```

**Complejidad:** O(n) tiempo, O(n) espacio (stack de recursión)

## 3. **Con estructura de lista completa**

