        prev = curr       // avanza prev
        curr = next       // avanza curr
    }
    return prev // nueva cabeza
}

func main() {
    head := &Node{1, &Node{2, &Node{3, nil}}}
    head = Reverse(head)
    for n := head; n != nil; n = n.Next {
        fmt.Print(n.Val, " ") // 3 2 1
    }
}
```

## Versión recursiva (O(n) tiempo, O(n) pila)

```go
func ReverseRec(head *Node) *Node {
    if head == nil || head.Next == nil {
        return head
    }
    newHead := ReverseRec(head.Next)
    head.Next.Next = head // el siguiente apunta de vuelta a head
    head.Next = nil
    return newHead
}
```

## Notas

- La función devuelve la nueva cabeza, así que hay que reasignarla: `head = Reverse(head)`.
- Una lista vacía (`nil`) o de un solo nodo funciona sin tratamiento especial.
- Prefiere la iterativa: no consume pila, y en Go una lista muy larga podría hacer crecer mucho la pila con la recursiva.
- Si usas `container/list` de la biblioteca estándar, no trae un método para invertir. Tendrías que recorrerla con `MoveToFront` sobre cada elemento:

```go
for e := l.Front(); e != nil; {
    next := e.Next()
    l.MoveToFront(e)
    e = next
}
```

Esto deja la lista invertida: cada elemento recorrido pasa al frente, y el último en moverse queda primero.

